use vstd::prelude::*;

verus! {
    spec fn transform(s: &Vec<i8>, i: nat) -> i8
        requires
            i < s.len() as nat,
    {
        if i % 3 == 0 {
            s[(i + 2) as usize]
        } else if i % 3 == 1 {
            s[(i - 1) as usize]
        } else {
            s[i as usize]
        }
    }

    fn decode_cyclic(s: &Vec<i8>) -> (res: Vec<i8>)
        requires
            s.len() <= 0x1_0000_0000, // Ensure the length of the input vector is within reasonable bounds
        ensures
            res.len() == s.len() &&
            forall |i: nat| (i < s.len() as nat) ==> (res[i as usize] == transform(s, i)),
    {
        let L = s.len() as nat;
        let P = L - (L % 3);

        let mut res = vec![0i8; L as usize]; // Initialize the result vector

        // Fill the result vector according to the transformation rules
        let mut i: nat = 0;
        while i < P
            invariant
                i <= P,
                res.len() == L as usize,
                forall |j: nat| (j < i) ==> (res[j as usize] == transform(s, j)),
            decreases P - i,
        {
            res[i as usize] = transform(s, i);
            i = i + 1;
        }

        // Copy the remaining elements unchanged
        while i < L
            invariant
                i <= L,
                res.len() == L as usize,
                forall |j: nat| (j < P) ==> (res[j as usize] == transform(s, j)),
            decreases L - i,
        {
            res[i as usize] = s[i as usize];
            i = i + 1;
        }

        // Return the result vector
        res
    }
}

